<?php

namespace Starter\Ai\Agents;

use Illuminate\Contracts\Auth\Authenticatable;
use Starter\Ai\Models\AgentVersion;

/**
 * Server-side context of a tool call. The actor and the agent come from
 * the authenticated request, never from arguments generated by the model.
 */
final class ToolContext
{
    public function __construct(
        public readonly Authenticatable $actor,
        public readonly AgentVersion $version,
        public readonly string $surface = 'page',
        public ?string $conversationId = null,
        public ?string $requestId = null,
    ) {}

    public function config(): AgentConfig
    {
        return $this->version->settings();
    }
}
